<?php
require dirname(__DIR__) . '/bootstrap.php';
use App\Support\Database;

$fixtures=[];$competitions=[];
try{$pdo=Database::connection();$fixtures=$pdo->query("SELECT f.provider_id,f.kickoff,f.status,f.home_score,f.away_score,f.stats_imported,c.name competition_name,c.country_name,c.logo competition_logo,h.name home_name,h.logo home_logo,a.name away_name,a.logo away_logo FROM fixtures f JOIN competitions c ON c.id=f.competition_id JOIN teams h ON h.id=f.home_team_id JOIN teams a ON a.id=f.away_team_id WHERE c.prediction_enabled=1 AND f.kickoff>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY) ORDER BY f.kickoff ASC LIMIT 30")->fetchAll(PDO::FETCH_ASSOC);$competitions=$pdo->query("SELECT name,country_name,logo FROM competitions WHERE prediction_enabled=1 ORDER BY country_name,name LIMIT 12")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function dt(string $v,string $format):string{try{$d=new DateTime($v,new DateTimeZone('UTC'));$d->setTimezone(new DateTimeZone('Europe/Berlin'));return $d->format($format);}catch(Throwable){return '—';}}
function initials(string $v):string{$p=preg_split('/\s+/',trim($v));return strtoupper(substr($p[0]??'',0,1).substr($p[1]??'',0,1));}
$groups=[];foreach($fixtures as $f){$groups[$f['competition_name']][]=$f;}
?>
