<?php if(!$groups):?><div class="py-20 text-center"><div class="w-14 h-14 mx-auto rounded-full bg-emerald-50 grid place-items-center text-2xl">⚽</div><h2 class="font-bold mt-4">No fixtures available yet</h2><p class="text-sm text-slate-400 mt-1">The collector is preparing supported competition data.</p></div><?php else:?><?php foreach($groups as $competition=>$matches):?><div class="border-b border-slate-100 last:border-0"><div class="bg-slate-50 px-4 py-2.5 flex items-center justify-between"><div class="text-xs font-bold"><?=e($competition)?></div><div class="text-[10px] text-slate-400"><?=count($matches)?> matches</div></div><?php foreach($matches as $f):?><a href="match.php?id=<?=urlencode($f['provider_id'])?>" class="grid grid-cols-[50px_minmax(0,1fr)_70px] sm:grid-cols-[65px_minmax(0,1fr)_100px_85px] items-center gap-3 px-4 py-3 border-t border-slate-100 hover:bg-emerald-50/40 transition"><div class="text-center"><div class="text-xs font-bold"><?=e(dt($f['kickoff'],'H:i'))?></div><div class="text-[9px] text-slate-400 mt-1"><?=e(dt($f['kickoff'],'d M'))?></div></div><div class="min-w-0 space-y-2"><div class="flex items-center gap-2"><?php if($f['home_logo']):?><img src="<?=e($f['home_logo'])?>" class="w-5 h-5 object-contain"><?php else:?><span class="w-5 h-5 rounded-full bg-slate-100 grid place-items-center text-[7px] font-bold"><?=e(initials($f['home_name']))?></span><?php endif;?><span class="text-sm font-semibold truncate"><?=e($f['home_name'])?></span></div><div class="flex items-center gap-2"><?php if($f['away_logo']):?><img src="<?=e($f['away_logo'])?>" class="w-5 h-5 object-contain"><?php else:?><span class="w-5 h-5 rounded-full bg-slate-100 grid place-items-center text-[7px] font-bold"><?=e(initials($f['away_name']))?></span><?php endif;?><span class="text-sm font-semibold truncate"><?=e($f['away_name'])?></span></div></div><div class="text-center font-black text-sm"><?= $f['home_score']!==null?e($f['home_score'].' : '.$f['away_score']):'<span class="text-slate-300">—</span>' ?></div><div class="hidden sm:block text-right"><span class="inline-flex rounded-lg px-2.5 py-1 text-[10px] font-bold <?= $f['stats_imported']?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-500' ?>"><?= $f['stats_imported']?'DATA READY':'PREVIEW' ?></span></div></a><?php endforeach;?></div><?php endforeach;?><?php endif;?></section>
